def gini(l,r):
    n=len(l)+len(r)
    def g(v):
        if len(v)==0: return 0
        p=v.mean(); return 2*p*(1-p)*len(v)/n
    return g(l)+g(r)
def cart(Xm,ym,depth):
    if depth==0 or len(set(ym))==1 or len(ym)<8: return ('leaf', ym.mean()>=0.5)
    best=None
    for j in range(Xm.shape[1]):
        vals=sorted(set(Xm[:,j]))
        for t in vals[:-1]:
            m=Xm[:,j]<=t
            s=gini(ym[m],ym[~m])
            if best is None or s<best[0]: best=(s,j,t)
    if best is None: return ('leaf', ym.mean()>=0.5)
    s,j,t=best
    m=Xm[:,j]<=t
    return ('node',j,t,cart(Xm[m],ym[m],depth-1),cart(Xm[~m],ym[~m],depth-1))
def pr(tree,keys,ind=''):
    if tree[0]=='leaf': print(ind,'->',tree[1]); return
    _,j,t,l,r=tree
    print(ind,f'{keys[j]}<={t}'); pr(l,keys,ind+'  '); print(ind,'else'); pr(r,keys,ind+'  ')
